fn ult(version, rnd, player, data, positioning_score, target) -> Option<Input>   // abstract_input.rs:280

// --- 1) 자기 챔피언 얻기 (281) ---
team = player.info.team              // PlayerState+0x930
if team >= 2 { panic_bounds_check }
pos  = player.info.position.as_index()   // PlayerState+0x9c0, i32 in [0,5)
champ = data.cache.player_champion[team][pos]    // AbstractGameWithCache+0x1e0, [[Option<&Entity>;5];2]
if champ == null { return None }         // 블록 25

// --- 2) 궁 사용 가능? (282~283) ---
if !Entity::can_ult(champ) { return None }        // 블록 27

// --- 3) 궁 이펙트 (286) ---
// Entity::ult_effect(entity.rs:1700) 인라인:
effect = if champ.level > 4 { &champ.ult_effect }   // Entity+0x5c8 > 4, Entity+0x538
         else { &<정적 상수 Option::<Effect>::None> } // @anon....16 = 48바이트 undef + FF FF FF FF
if effect.casting(=Effect+0x30) == -1 { return None }   // Option 니치 None, 블록 40

// --- 4) 대상 적합성 (288~289) ---
if !CastingTarget::check(&effect.target /*Effect+0x28*/, champ, target) { return None }  // 블록 41

// --- 5) 시전 타입별 사거리 선검사 (293~313) ---
// switch effect.casting  { 1 => Position, 2 => Direction, else(0 Targeting / 3 None) => 곧바로 6) }
match effect.casting {
  CastingType::Position => {                      // 블록 44, 라인 296
     if !(*effect.ty)[vtable+0x118]() { goto 6) }       // bool 반환. 슬롯 이름 unknown
     range = linear_cast_range_with_margin(effect, champ, target)   // 라인 297
     if distance_sq(champ.x,champ.y, target.x,target.y) > range*range { goto 7) }  // 라인 299
     goto 6)
  }
  CastingType::Direction => {                     // 블록 57, 라인 310
     if (*effect.ty)[vtable+0xf8]().0 != 1 { goto 6) }  // {i64,i64} 반환, .0==1 인지. 슬롯 이름 unknown
     range = linear_cast_range_with_margin(effect, champ, target)   // 라인 311
     if distance_sq(champ.x,champ.y, target.x,target.y) > range*range { goto 7) }  // 라인 313
     goto 6)
  }
  _ => goto 6)
}
// distance_sq(game-core/utils.rs:6~9) = abs_diff(ax,bx)^2 + abs_diff(ay,by)^2  (부호없음, 인라인)

// --- 6) 실제 입력 만들기 (블록 95) ---
cd = Entity::cooldown_reduce(champ, true)
input_target: Option<InputTarget> =
    get_input_target(version, rnd, player, data, positioning_score, target, effect, cd)
if input_target.tag == -1 { goto 7) }             // 라인 325
return Some(Input::Ult { target: input_target })  // 라인 326: sret+0x8 에 24B memcpy, sret+0x0 = 5

// --- 7) 사거리 밖/타깃 실패 → 접근 이동 (블록 122, 라인 328~341) ---
// Entity::is_visible_from(self=target, entity=champ) 인라인 (entity.rs:1481~1483)
visible = match champ.team {                       // Entity+0x0 태그
            TeamType::Neutral => true,             // player_team()=None → 기본 true
            TeamType::Player(t) => { if t>=2 {panic_bounds_check}
                                     target.visible_state[t].tag == 0 /*Visible*/ }  // Entity+0x38, stride 24
          }
if !visible {                                      // 라인 340 (블록 138)
    return safe_move_avoiding_enemy_well(version, player, data, champ, target.x, target.y)
}
// 보일 때 = 사거리 안쪽으로 붙는 목표점 계산 (라인 329~338, 블록 143~232)
dx = champ.x - target.x                            // i64 부호 뺄셈 (여기선 abs_diff 아님)
dy = champ.y - target.y
sz = game_core::utils::isqrt(dx*dx + dy*dy)

// effect_range_with_radii(abstract_input.rs:190~192) 인라인:
champ_r = if effect.casting == CastingType::Targeting { champ.radius() } else { 0 }
//   Entity::radius() = if buff.radius_mult==0 { radius } else { radius*(radius_mult+100)/100 }
total_range = effect.range                                   // Effect+0x10
            + champ_r
            + champ.stat_buff_cached.range                   // Entity+0x438
            + (champ.level - 1) * effect.growth_range        // Entity+0x5c8, Effect+0x18
            + Effect::range_adjust(effect, champ, target)
            + target.radius()
from_distance = total_range.saturating_sub(150000)           // 라인 333

if sz == 0 { panic_const_div_by_zero }
x = target.x + (from_distance * dx) / sz                     // 라인 334 (sdiv)
y = target.y + (from_distance * dy) / sz                     // 라인 335
(x, y) = Game::adjust_position(data.context.map, data.context.setting, x, y)  // 라인 336
return safe_move_avoiding_enemy_well(version, player, data, champ, x, y)      // 라인 338
